	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ListLastTranscriptTurnsRow
	for rows.Next() {
		var i ListLastTranscriptTurnsRow
		if err := rows.Scan(&i.Seq, &i.Role, &i.Content); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
